import System.Exception;import System.ArgumentException;import System.Collections.*;import java.nio.file.*;import java.util.*;
class ExceptionDataFloatingKeyEqualityProbe {
 interface Action{Object run();}
 static String units(String s){if(s==null)return "~";StringJoiner j=new StringJoiner(",");for(char c:s.toCharArray())j.add(Integer.toString(c));return j.toString();}
 static Object key(String s){if(s.charAt(0)=='F')return Float.valueOf(Float.intBitsToFloat(Integer.parseUnsignedInt(s.substring(1),16)));return Double.valueOf(Double.longBitsToDouble(Long.parseUnsignedLong(s.substring(1),16)));}
 static String normal(Object v){if(v instanceof DictionaryEntry e)return "E"+normal(e.get_Key())+"="+e.get_Value();if(v instanceof Float f)return "F"+String.format(Locale.ROOT,"%08x",Float.floatToRawIntBits(f));if(v instanceof Double d)return "D"+String.format(Locale.ROOT,"%016x",Double.doubleToRawLongBits(d));return v==null?"~":"V"+v;}
 static String outcome(Action a,String kind){try{Object v=a.run();return "OK|"+kind+"|"+(kind.equals("void")?"~":kind.equals("bool")?((Boolean)v?"1":"0"):kind.equals("current")?normal(v):v==null?"~":v.toString());}catch(Exception e){return "ERR|"+e.getClass().getName()+"|"+units(e.get_Message())+"|"+e.get_HResult()+"|"+units(e instanceof ArgumentException x?x.get_ParamName():null);}}
 static String contents(IDictionary d){StringJoiner j=new StringJoiner(";");IDictionaryEnumerator c=d.GetEnumerator();while(c.MoveNext())j.add(normal(c.get_Entry()));return j.toString();}
 static void check(String a,String e,String c){if(!a.equals(e))throw new AssertionError(c+" actual="+a+" expected="+e);}
 public static void main(String[] args)throws java.lang.Exception{IDictionary d=null;Object stored=null,query=null;int profiles=0,steps=0,groups=0;for(String line:Files.readAllLines(Path.of(args[0]))){String[] p=line.split("\t",-1);if(p[0].equals("N")){d=new Exception("floating equality").get_Data();stored=key(p[1]);query=key(p[2]);check(normal(stored),p[1],"stored raw transport");check(normal(query),p[2],"query raw transport");profiles++;continue;}final IDictionary dictionary=d;final Object s=stored,q=query;if(p[0].equals("I")){check(outcome(()->{dictionary.Add(s,"initial");return null;},"void"),p[1],"initial "+line);groups++;continue;}
 IEnumerator[] cursors={d.GetEnumerator(),d.get_Keys().GetEnumerator(),d.get_Values().GetEnumerator()};for(int i=0;i<3;i++){final IEnumerator c=cursors[i];check(outcome(c::MoveNext,"bool"),p[2+i],"before "+line);groups++;}String r=switch(p[1]){case "read"->outcome(()->dictionary.get_Item(q),"value");case "contains"->outcome(()->dictionary.Contains(q),"bool");case "write"->outcome(()->{dictionary.set_Item(q,"updated");return null;},"void");case "add"->outcome(()->{dictionary.Add(q,"added");return null;},"void");case "remove","removeEmpty"->outcome(()->{dictionary.Remove(q);return null;},"void");case "clear","clearEmpty"->outcome(()->{dictionary.Clear();return null;},"void");default->throw new AssertionError();};check(r,p[5],"result "+line);groups++;
 for(int i=0;i<3;i++){final IEnumerator c=cursors[i];int o=8+i*3;check(outcome(c::get_Current,"current"),p[o],"current "+line);check(outcome(c::MoveNext,"bool"),p[o+1],"move "+line);check(outcome(()->{c.Reset();return null;},"void"),p[o+2],"reset "+line);groups+=3;}
 check(Integer.toString(d.get_Count()),p[6],"count "+line);check(contents(d),p[7],"contents "+line);groups+=2;steps++;}java.lang.System.out.println("PASS floating key equality profiles="+profiles+" steps="+steps+" groups="+groups);}
}
